+++ CelikPanel's text
@@ -1,5 +1,13 @@
 # Nginx vhost for set10-r3.test
-# Generated by CelikPanel — do not edit by hand / elle düzenlemeyin
+# Written by CelikPanel. Put your own additions in /etc/nginx/celikpanel-sites.d/set10-r3.test/*.conf;
