+# your file and asks you before it replaces it. Keep the lines that include
+# /etc/nginx/celikpanel-managed.d/set10-r3.test: that directory is CelikPanel's (certificate
+# validation) and CelikPanel writes there without touching this file.
+# CelikPanel yazdı. Kendi eklemeleriniz /etc/nginx/celikpanel-sites.d/set10-r3.test/*.conf içine;
+# CelikPanel oraya hiç yazmaz. Bu dosyayı değiştirirseniz CelikPanel
+# dosyanızı korur ve değiştirmeden önce size sorar. /etc/nginx/celikpanel-managed.d/set10-r3.test
+# satırlarını koruyun: o dizin CelikPanel'indir (sertifika doğrulaması).
 # Site ID: 3 · Project type: php
 server {
     listen 80;
@@ -9,11 +17,8 @@
     access_log /var/log/nginx/set10-r3.test-access.log;
     error_log /var/log/nginx/set10-r3.test-error.log;

-    # Root-owned validation content only; never tenant public_html.
-    location ^~ /.well-known/acme-challenge/ {
-        root /var/lib/celikpanel-agent/acme-http-01/subscriptions/2/domains/3;
-        try_files $uri =404;
-    }
+    # CelikPanel's own parts of this site (certificate validation) / CelikPanel'in parçaları
+    include /etc/nginx/celikpanel-managed.d/set10-r3.test/*.conf;

     root /var/www/celikpanel/subscriptions/2/sites/3/public_html;
     index index.php index.html index.htm;
@@ -22,9 +27,13 @@

         try_files $uri $uri/ /index.php?$query_string;
     }
-
     location ~ \.php$ {
-        include snippets/fastcgi-php.conf;
+        fastcgi_split_path_info ^(.+?\.php)(/.*)$;
+        try_files $fastcgi_script_name =404;
+        set $path_info $fastcgi_path_info;
+        fastcgi_param PATH_INFO $path_info;
+        fastcgi_index index.php;
+        include fastcgi.conf;
         fastcgi_pass unix:/var/run/php/php8.4-fpm-site3.sock;
         fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name;
         include fastcgi_params;
@@ -33,8 +42,6 @@
         deny all;
     }

-    # set10: added by the server owner by hand
-    location /owner-extra/ {
-        return 200 "owner";
-    }
+    # Your additions for this site (server context) / Bu site için eklemeleriniz
+    include /etc/nginx/celikpanel-sites.d/set10-r3.test/*.conf;
 }

